(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-866":{scenario:{company:"Hải Đăng Learning Studio",supervisor:{name:"Vũ Ngọc Lan",role:{vi:"Trưởng nhóm Thiết kế Học tập",en:"Learning Design Lead"}},ref_code:"ID-6120",title:{vi:"Đúng mục tiêu. Đúng số liệu. Đúng bản quyền.",en:"Right objective. Right data. Right licensing."},brief:{vi:"Học phần e-learning ID-6120 “An toàn thông tin cho nhân viên mới” đã chạy thử 1 tháng. Báo cáo LMS: 480 học viên được ghi danh, 400 người đã mở khóa học, 310 người hoàn thành và đạt bài kiểm tra cuối (số liệu mô phỏng). Mục tiêu 3 là “Học viên cấu hình được quy tắc lọc thư nghi lừa đảo trên hộp thư công ty”. Đối chiếu bản thiết kế nháp với ma trận mục tiêu đã duyệt, sửa mức Bloom của mục tiêu 3 và tỷ lệ hoàn thành (%), rồi lập báo cáo có căn cứ.",en:"E-learning module ID-6120 “Information security for new staff” has been piloted for 1 month. LMS report: 480 learners enrolled, 400 opened the course, 310 completed and passed the final test (training data). Objective 3 is “Learners can configure a phishing filter rule in the company mailbox”. Compare the draft design with the approved objective matrix, correct the Bloom level of objective 3 and the completion rate (%), then write an evidence-based report."},reference_title:{vi:"Ma trận mục tiêu & khung đánh giá đã duyệt · ID-6120",en:"Approved objective matrix & evaluation framework · ID-6120"},fields:[{id:"BLOOM_LVL",label:{vi:"Mức Bloom của mục tiêu 3",en:"Bloom level of objective 3"},initial:"UNDERSTAND",expected:"APPLY",choices:["UNDERSTAND","APPLY","EVALUATE"],reference:"Ma trận mục tiêu học tập",hint:{vi:"Xác định động từ hành động: học viên thực hiện một quy trình trong tình huống cụ thể hay chỉ giải thích khái niệm?",en:"Find the action verb: do learners carry out a procedure in a concrete situation or only explain a concept?"}},{id:"COMPL_RATE",label:{vi:"Tỷ lệ hoàn thành khóa học (%)",en:"Course completion rate (%)"},initial:"77.5",expected:"64.6",reference:"Khung chỉ số đánh giá khóa học",ref_value:{vi:"Ghi danh 480; đã mở khóa học 400; hoàn thành và đạt 310",en:"Enrolled 480; opened the course 400; completed and passed 310"},hint:{vi:"Kiểm tra mẫu số: khung đánh giá tính trên toàn bộ người được giao học, không phải người đã bắt đầu.",en:"Check the denominator: the framework uses everyone assigned to the course, not only those who started."}}],sop32:{vi:"Tỷ lệ hoàn thành = số học viên hoàn thành và đạt / tổng số học viên được ghi danh x 100, làm tròn 1 chữ số thập phân; không dùng số người đã mở khóa học làm mẫu số.",en:"Completion rate = learners who completed and passed / total enrolled learners x 100, rounded to 1 decimal place; never use learners who opened the course as the denominator."},context:{label:"LMS / ID-6120",metrics:[{label:{vi:"Ghi danh",en:"Enrolled"},value:"480"},{label:{vi:"Đã mở khóa học",en:"Opened the course"},value:"400"},{label:{vi:"Hoàn thành và đạt",en:"Completed and passed"},value:"310"}]},crisis:{vi:"Khách hàng nội bộ nhắn: “Chèn nguyên 6 video bài giảng tải từ một khóa học trả phí trên mạng vào học phần cho kịp ra mắt thứ Hai. Học nội bộ thôi, không ai kiểm tra bản quyền đâu.”",en:"The internal client writes: “Embed the 6 lecture videos downloaded from a paid online course so we can launch on Monday. It is internal only, nobody checks copyright.”"},options:{safe:{vi:"Từ chối dùng video không có giấy phép, báo trưởng nhóm; đề xuất tự quay video ngắn theo kịch bản, dùng tư liệu có giấy phép hoặc lùi ngày ra mắt phần video.",en:"Refuse to use unlicensed videos and inform the lead; propose short in-house videos from a script, licensed assets or a later release of the video part."},shortcut:{vi:"Chèn 6 video vào học phần cho kịp tiến độ, sau này có thời gian sẽ thay.",en:"Embed the 6 videos to meet the deadline and replace them later when there is time."},wait:{vi:"Dừng toàn bộ dự án và chờ khách hàng nội bộ tự tìm tư liệu khác.",en:"Stop the whole project and wait for the internal client to find other materials."}},questions:{vi:["Vì sao mục tiêu 3 thuộc mức APPLY và tỷ lệ hoàn thành đúng là 64.6%? Điều đó thay đổi thiết kế bài kiểm tra thế nào?","Rủi ro pháp lý khi dùng nội dung không có giấy phép trong đào tạo nội bộ là gì? Bạn đề xuất phương án nào?"],en:["Why is objective 3 at the APPLY level and why is the completion rate 64.6%? How does this change the assessment design?","What legal risks come from using unlicensed content in internal training? Which alternative do you propose?"]},hints:{vi:["Đặt bản thiết kế nháp cạnh ma trận mục tiêu, đối chiếu động từ hành động với thang Bloom.","Áp dụng SOP mục 3.2: chọn đúng mẫu số trước khi tính tỷ lệ phần trăm.","Đọc lại SOP mục 4.2: mọi tư liệu đưa vào học phần phải có quyền sử dụng hợp pháp và được ghi nguồn."],en:["Place the draft design next to the objective matrix and match the action verb to the Bloom scale.","Apply SOP 3.2: pick the correct denominator before computing the percentage.","Re-read SOP 4.2: every asset in a module must be legally licensed and credited."]}},learning:{summary:{vi:"Chuyên viên thiết kế chương trình và học liệu số phân tích nhu cầu học tập, viết mục tiêu đo lường được, thiết kế trải nghiệm học trực tuyến và kết hợp, xây dựng kịch bản, tương tác, bài kiểm tra và đánh giá hiệu quả sau triển khai. Vai trò này kết hợp khoa học học tập, công nghệ giáo dục, tư duy dữ liệu và trách nhiệm về bản quyền, khả năng tiếp cận.",en:"An instructional designer and EdTech specialist analyzes learning needs, writes measurable objectives, designs online and blended experiences, builds storyboards, interactions and assessments, and evaluates impact after rollout. The role combines learning science, educational technology, data thinking and responsibility for copyright and accessibility."},responsibilities:{vi:["Phân tích nhu cầu, đối tượng học và khoảng cách năng lực cùng chuyên gia nội dung.","Viết mục tiêu học tập theo thang Bloom và lập ma trận liên kết mục tiêu, hoạt động, đánh giá.","Xây dựng kịch bản (storyboard), tương tác, video, bài tập tình huống trên công cụ soạn bài giảng.","Đóng gói SCORM hoặc xAPI, kiểm thử trên LMS và bảo đảm khả năng tiếp cận.","Đánh giá hiệu quả theo mô hình Kirkpatrick và cải tiến dựa trên dữ liệu học tập."],en:["Analyze needs, audiences and competency gaps with subject matter experts.","Write Bloom-based objectives and build a matrix aligning objectives, activities and assessments.","Build storyboards, interactions, videos and scenario exercises in authoring tools.","Package SCORM or xAPI content, test it on the LMS and ensure accessibility.","Evaluate impact with the Kirkpatrick model and improve from learning data."]},competencies:[{name:{vi:"Thiết kế theo mục tiêu",en:"Objective-driven design"},desc:{vi:"Viết mục tiêu có động từ đo được và chọn hình thức đánh giá khớp đúng mức nhận thức.",en:"Write objectives with measurable verbs and choose assessments that match the cognitive level."}},{name:{vi:"Khoa học học tập",en:"Learning science"},desc:{vi:"Áp dụng nguyên tắc đa phương tiện, giảm tải nhận thức và luyện tập truy xuất.",en:"Apply multimedia principles, cognitive load reduction and retrieval practice."}},{name:{vi:"Công nghệ học liệu số",en:"Digital learning technology"},desc:{vi:"Thành thạo công cụ soạn bài giảng, chuẩn SCORM, xAPI và cấu hình LMS.",en:"Master authoring tools, SCORM and xAPI standards and LMS configuration."}},{name:{vi:"Phân tích dữ liệu học tập",en:"Learning analytics"},desc:{vi:"Đọc báo cáo LMS, chọn đúng mẫu số và rút ra hành động cải tiến.",en:"Read LMS reports, choose correct denominators and derive improvement actions."}},{name:{vi:"Bản quyền & khả năng tiếp cận",en:"Copyright & accessibility"},desc:{vi:"Chỉ dùng tư liệu có giấy phép, ghi nguồn và thiết kế phụ đề, tương phản màu theo WCAG.",en:"Use only licensed assets, credit sources and design captions and color contrast to WCAG."}}],knowledge:{vi:["Mô hình ADDIE (Phân tích, Thiết kế, Phát triển, Triển khai, Đánh giá) và các mô hình lặp nhanh như SAM.","Thang Bloom sửa đổi (Anderson & Krathwohl, 2001): Nhớ, Hiểu, Vận dụng, Phân tích, Đánh giá, Sáng tạo.","Mô hình đánh giá đào tạo 4 cấp độ Kirkpatrick: Phản ứng, Học tập, Hành vi, Kết quả.","Chuẩn đóng gói và theo dõi học liệu SCORM 1.2, SCORM 2004 và xAPI.","Hướng dẫn khả năng tiếp cận nội dung web WCAG 2.1 và 2.2 của W3C.","Luật Sở hữu trí tuệ số 50/2005/QH11 (sửa đổi, bổ sung) về quyền tác giả đối với tác phẩm điện ảnh, bài giảng."],en:["The ADDIE model (Analysis, Design, Development, Implementation, Evaluation) and agile models such as SAM.","Revised Bloom's taxonomy (Anderson & Krathwohl, 2001): Remember, Understand, Apply, Analyze, Evaluate, Create.","Kirkpatrick's four-level training evaluation: Reaction, Learning, Behavior, Results.","Content packaging and tracking standards SCORM 1.2, SCORM 2004 and xAPI.","W3C Web Content Accessibility Guidelines WCAG 2.1 and 2.2.","Intellectual Property Law No. 50/2005/QH11 (as amended) on copyright in films and lectures."]},tools:["Công cụ soạn bài giảng tương tác","Hệ thống quản lý học tập (LMS)","Kho lưu trữ dữ liệu học tập (LRS)","Phần mềm quay và dựng video màn hình","Công cụ thiết kế đồ họa","Mẫu storyboard và ma trận mục tiêu"],kpis:{vi:["Tỷ lệ hoàn thành và tỷ lệ đạt tính trên tổng số học viên được ghi danh.","Mức cải thiện điểm trước và sau học, mức độ áp dụng trên công việc.","Số học phần ra mắt đúng hạn, đúng ngân sách.","Số lỗi bản quyền, khả năng tiếp cận phát hiện khi kiểm định (mục tiêu bằng 0)."],en:["Completion and pass rates over all enrolled learners.","Pre-post score gain and on-the-job application level.","Modules launched on time and on budget.","Copyright and accessibility issues found in review (target zero)."]},day:[{time:"08:30",vi:"Xem bảng điều khiển LMS, kiểm tra tỷ lệ hoàn thành và câu hỏi học viên hay sai.",en:"Check the LMS dashboard, completion rates and the most-missed questions."},{time:"10:00",vi:"Phỏng vấn chuyên gia nội dung, chốt mục tiêu và ma trận đánh giá học phần mới.",en:"Interview the subject matter expert and finalize objectives and the assessment matrix."},{time:"13:30",vi:"Viết storyboard tình huống phân nhánh và dựng tương tác trên công cụ soạn bài giảng.",en:"Write a branching scenario storyboard and build interactions in the authoring tool."},{time:"15:30",vi:"Kiểm thử gói SCORM trên LMS, rà phụ đề, độ tương phản và điều hướng bàn phím.",en:"Test the SCORM package on the LMS and check captions, contrast and keyboard navigation."},{time:"17:00",vi:"Cập nhật nhật ký bản quyền tư liệu và báo cáo tiến độ cho trưởng nhóm.",en:"Update the asset license log and report progress to the lead."}],mistakes:{vi:["Viết mục tiêu mức Hiểu nhưng yêu cầu học viên thực hiện thao tác, khiến bài kiểm tra trắc nghiệm ghi nhớ không đo đúng năng lực.","Tính tỷ lệ hoàn thành trên số người đã mở khóa học, làm số liệu đẹp hơn thực tế.","Dùng video, hình ảnh tải từ mạng không có giấy phép, vi phạm quyền tác giả."],en:["Labelling an objective as Understand while it requires a task, so a recall quiz fails to measure the skill.","Computing completion over learners who opened the course, inflating the result.","Using videos or images downloaded online without a license, infringing copyright."]},career:[{vi:"Chuyên viên phát triển học liệu số",en:"E-learning developer"},{vi:"Chuyên viên thiết kế chương trình học",en:"Instructional designer"},{vi:"Trưởng nhóm thiết kế học tập",en:"Senior learning experience designer / lead"},{vi:"Giám đốc học liệu số & công nghệ giáo dục",en:"Head of digital learning & EdTech"}],glossary:[{term:"Learning objective",vi:"Mục tiêu học tập mô tả hành vi đo được mà học viên làm được sau khi học.",en:"A statement of measurable behavior learners can perform after learning."},{term:"Storyboard",vi:"Kịch bản chi tiết từng màn hình gồm nội dung, hình ảnh, âm thanh và tương tác.",en:"Screen-by-screen script of content, visuals, audio and interactions."},{term:"SCORM",vi:"Chuẩn đóng gói học liệu số để LMS ghi nhận trạng thái hoàn thành và điểm số.",en:"A content packaging standard that lets an LMS track completion and scores."},{term:"xAPI",vi:"Chuẩn ghi nhận trải nghiệm học dạng câu lệnh, lưu vào kho LRS, kể cả ngoài LMS.",en:"A standard that records learning experiences as statements in an LRS, even outside the LMS."},{term:"Constructive alignment",vi:"Liên kết đồng bộ giữa mục tiêu, hoạt động học và hình thức đánh giá.",en:"Consistent alignment between objectives, learning activities and assessments."}],quiz:[{q:{vi:"Khóa học có 600 người được ghi danh, 450 người mở khóa học, 390 người hoàn thành và đạt. Tỷ lệ hoàn thành theo chuẩn là bao nhiêu?",en:"A course has 600 enrolled, 450 opened it and 390 completed and passed. What is the standard completion rate?"},options:{vi:["86,7%","75,0%","65,0%","55,0%"],en:["86.7%","75.0%","65.0%","55.0%"]},answer:2,explain:{vi:"Tỷ lệ hoàn thành = 390 / 600 x 100 = 65,0%; mẫu số là tổng số người được ghi danh.",en:"Completion = 390 / 600 x 100 = 65.0%; the denominator is total enrollment."}},{q:{vi:"Mục tiêu “Học viên so sánh hai phương án và chọn phương án tối ưu có lập luận” thuộc mức Bloom nào?",en:"The objective “Learners compare two options and justify the best one” is at which Bloom level?"},options:{vi:["Đánh giá","Nhớ","Hiểu","Vận dụng"],en:["Evaluate","Remember","Understand","Apply"]},answer:0,explain:{vi:"Đưa ra phán đoán có lập luận dựa trên tiêu chí là đặc trưng của mức Đánh giá.",en:"Making a justified judgment against criteria is the hallmark of the Evaluate level."}},{q:{vi:"Quan sát nhân viên áp dụng kỹ năng tại nơi làm việc sau 2 tháng là cấp độ nào trong mô hình Kirkpatrick?",en:"Observing staff applying skills at work 2 months later is which Kirkpatrick level?"},options:{vi:["Cấp 1 - Phản ứng","Cấp 2 - Học tập","Cấp 4 - Kết quả","Cấp 3 - Hành vi"],en:["Level 1 - Reaction","Level 2 - Learning","Level 4 - Results","Level 3 - Behavior"]},answer:3,explain:{vi:"Cấp 3 đo sự thay đổi hành vi, mức độ áp dụng kiến thức vào công việc thực tế.",en:"Level 3 measures behavior change and on-the-job application."}},{q:{vi:"Khách hàng yêu cầu dùng video tải từ khóa học trả phí của đơn vị khác. Bạn làm gì?",en:"The client asks you to use videos downloaded from another provider's paid course. What do you do?"},options:{vi:["Dùng vì chỉ học nội bộ","Từ chối, báo cáo và đề xuất tư liệu có giấy phép hoặc tự sản xuất","Cắt ngắn video để tránh bị phát hiện","Chờ khách tự quyết"],en:["Use them since it is internal","Refuse, escalate and propose licensed or in-house content","Trim the videos to avoid detection","Wait for the client to decide"]},answer:1,explain:{vi:"Dùng tác phẩm không được phép là xâm phạm quyền tác giả kể cả trong nội bộ; phải có phương án hợp pháp.",en:"Using works without permission infringes copyright even internally; a lawful alternative is required."}}],tools_en:["Interactive e-learning authoring tool","Learning management system (LMS)","Learning record store (LRS)","Screen recording and video editing software","Graphic design tool","Storyboard and objectives matrix templates"]}}})})(window.KKR);
